import pathlib,os,subprocess,base64
os.umask(0o077)
state=pathlib.Path('/workspace/.aj-diagnostics')
old=base64.b64decode('').decode()
new=base64.b64decode('').decode()
for label,path in [('source',pathlib.Path('/opt/aj/ziomalskit/h3/app/model_health.py')),('deployed',pathlib.Path('/workspace/H3_VAST_MOBILE/app/model_health.py'))]:
 text=path.read_text()
 if new in text:continue
 assert old in text,'Unexpected bridge verifier source'
 (state/('model-health-before-'+label+'.py')).write_text(text)
 temp=path.with_suffix('.aj-tmp');temp.write_text(text.replace(old,new));os.chmod(temp,0o644);temp.replace(path)
 print('Docker node path compatibility fixed:',label,flush=True)
with (state/'final-start-retry.log').open('wb') as log:
 result=subprocess.run(['aj-docker','start'],stdout=log,stderr=subprocess.STDOUT,timeout=900)
text=(state/'final-start-retry.log').read_text(errors='replace')
print(text[-24000:]);print('AJ_START_EXIT',result.returncode)
raise SystemExit(result.returncode)
